solution:
fn count_greater[T: Ord](items: &Vec[T], threshold: T) -> Int
  ensures: result >= 0;
  ensures: result <= items.len();
{
  var count = 0;
  for item in items {
    if item > threshold { count = count + 1; }
  }
  return count;
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(1); v.push(5); v.push(3); v.push(7); v.push(2);
  return count_greater[Int](&v, 3);
}
